    for (var gi = 0; gi < grat.length; gi++) {
      ctx.beginPath(); var on = false;
      for (var gj = 0; gj < grat[gi].length; gj++) { var q = proj(grat[gi][gj]); if (q.d <= 0) { on = false; continue; } if (!on) { ctx.moveTo(q.x, q.y); on = true; } else ctx.lineTo(q.x, q.y); }
      ctx.stroke();
    }

