    var act = arcs[origin];
    strokeArc(act, 0, 1, 0.18, 1.2, [3, 5], now);
    if (travel > 0) strokeArc(act, 0, travel, 1, 2.4, null, now);
    if (travel > 0 && travel < 1) particle(act, travel, 4.2, 1, true);

    // chegada
