      if (left + cw > W - 4) { left = mp.x - cw - 34; right = false; }
      if (topY < 4) topY = mp.y + 30;
      if (W < 460) { left = W - cw - 2; topY = H - ch - 2; right = true; } // telas estreitas: cartão no canto inferior
      left = Math.max(4, Math.min(W - cw - 4, left));
